renderer.fragment:
void main(){
  float n = max(floor(u_barCount + 0.5), 1.0);
  float x = uv.x * n;
  float i = floor(x);
  float f = fract(x);
  float t = iTime * u_speed;
  float s = hash1(i + 1.0);
  float wave = 0.5 + 0.5 * sin(t * (2.0 + 3.0 * s) + s * 6.28318);
  float jitter = 0.55 + 0.45 * noise(vec2(i * 0.37, t * 1.3));
  float h = (0.12 + 0.88 * wave * jitter) * mix(1.0, 0.65, i / n);
  float yy = u_mirror > 0.5 ? abs(uv.y - 0.5) * 2.0 : 1.0 - uv.y;
  float hg = u_gap * 0.5;
  float fx = max(fwidth(x), 1e-4);
  float fy = max(fwidth(yy), 1e-4);
  float bar = smoothstep(hg - fx, hg + fx, f) * (1.0 - smoothstep(1.0 - hg - fx, 1.0 - hg + fx, f));
  float fill = 1.0 - smoothstep(h - fy, h + fy, yy);
  vec3 col = mix(u_colorLow, u_colorHigh, clamp(yy, 0.0, 1.0));
  float a = bar * fill;
  fragColor = vec4(col * a, a);
}
